function buildKorea(){if(korea)return korea;const T=window.__KOREA_TOPO;if(!T||typeof topojson==='undefined')return null;const st=T.sido,gt=T.sigungu,sGeo=st.objects.sido.geometries,gGeo=gt.objects.sigungu.geometries;const zone=g=>krZone[g.properties.CODE.slice(0,2)]||'기타';const sido=topojson.feature(st,st.objects.sido).features.map((f,i)=>krFeature(f,'SD'+sGeo[i].properties.CODE,sGeo[i].properties.KOR_NM));const sigungu=topojson.feature(gt,gt.objects.sigungu).features.map((f,i)=>krFeature(f,'SG'+gGeo[i].properties.CODE,gGeo[i].properties.KOR_NM+(gGeo[i].properties.SIDO?' · '+gGeo[i].properties.SIDO.replace(/(특별시|광역시|특별자치시|특별자치도|도)$/,''):'')));const groups={};sGeo.forEach(g=>{const k=zone(g);(groups[k]=groups[k]||[]).push(g)});const kwon=Object.entries(groups).map(([name,geos])=>krFeature({geometry:topojson.merge(st,geos)},'KW'+name,name));const outline={type:'Feature',properties:{},geometry:topojson.merge(st,sGeo)};korea={kwon,sido,sigungu,outline,kwonMesh:topojson.mesh(st,st.objects.sido,(a,b)=>zone(a)!==zone(b)),sidoMesh:topojson.mesh(st,st.objects.sido,(a,b)=>a!==b),sigunguMesh:topojson.mesh(gt,gt.objects.sigungu,(a,b)=>a!==b)};return korea}
