function autoPlaceCountry(c,pending){const raw=c.assist&&c.assist!=='inherit'?c.assist:state.autoAssist,anchor=screen(countryAnchor(c)),b=countryBounds(c),size=c.size||state.fontSize;if(raw==='none'){c.pos=countryAnchor(c);return}if(raw==='smart'){const spot=insideSpot(c);if(spot){c.pos=spot;return}}const half=Math.max(size*.7,(c.text||'A').length*size*.34),gap=half+22;const occupied=state.countries.filter(v=>v!==c&&v.text&&!(pending&&pending.has(v))).map(v=>screen(v.pos));const others=state.countries.filter(v=>v!==c).map(v=>({f:features.find(f=>f.id===v.id),b:countryBounds(v)})).filter(o=>o.f);const cand=[];for(const side of[1,-1])for(const dy of[0,-1,1,-2,2])cand.push([side>0?b[1][0]+gap:b[0][0]-gap,anchor[1]+dy*size*1.35]);for(const sy of[-1,1])cand.push([anchor[0],sy>0?b[1][1]+size*.95:b[0][1]-size*.95]);let best=null,bestCost=Infinity;for(const raw of cand){const x=Math.max(half+12,Math.min(W-half-12,raw[0])),y=Math.max(size,Math.min(H-size,raw[1]));let cost=Math.abs(x-anchor[0])+1.35*Math.abs(y-anchor[1]);for(const q of occupied)if(Math.hypot(q[0]-x,q[1]-y)<size*1.8)cost+=1200;if(x>b[0][0]-4&&x<b[1][0]+4&&y>b[0][1]-4&&y<b[1][1]+4)cost+=500;const ll=geo([x,y]);if(ll&&Number.isFinite(ll[0])&&others.some(o=>x>=o.b[0][0]&&x<=o.b[1][0]&&y>=o.b[0][1]&&y<=o.b[1][1]&&d3.geoContains(o.f,ll)))cost+=900;if(cost<bestCost){bestCost=cost;best=[x,y]}}c.pos=geo(best||[anchor[0]+65,anchor[1]])||countryAnchor(c)}
