function download(blob,ext){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=($('filename').value.trim().replace(/[<>:"/\\|?*]/g,'_')||'세계지리_백지도')+ext;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function exportXml(){const prev=active;active=null;render();const copy=$('map').cloneNode(true);active=prev;render();copy.setAttribute('xmlns',NS);copy.setAttribute('width',state.mmW+'mm');copy.setAttribute('height',(state.mmW*H/W)+'mm');copy.setAttribute('preserveAspectRatio','none');copy.removeAttribute('style');copy.querySelectorAll('[data-editor],title').forEach(n=>n.remove());copy.querySelectorAll('*').forEach(n=>{n.removeAttribute('class');n.removeAttribute('data-country');n.removeAttribute('data-annotation')});return new XMLSerializer().serializeToString(copy)}
$('exportSvg').onclick=()=>{if(!ready)return;download(new Blob([exportXml()],{type:'image/svg+xml;charset=utf-8'}),'.svg');toast('SVG 벡터 지도를 저장했습니다.')};
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0}
async function withDpi(blob,dpi){const bytes=new Uint8Array(await blob.arrayBuffer()),chunk=new Uint8Array(21),v=new DataView(chunk.buffer);v.setUint32(0,9);chunk.set([112,72,89,115],4);v.setUint32(8,Math.round(dpi/0.0254));v.setUint32(12,Math.round(dpi/0.0254));chunk[16]=1;v.setUint32(17,crc32(chunk.subarray(4,17)));return new Blob([bytes.subarray(0,33),chunk,bytes.subarray(33)],{type:'image/png'})}
$('exportPng').onclick=async()=>{if(!ready)return;const btn=$('exportPng');btn.disabled=true;btn.textContent='이미지 만드는 중…';let url;try{await document.fonts.load('32px "KoPubLocal"');await document.fonts.ready;const width=exportInfo(),height=Math.round(width*H/W),xml=exportXml().replace(/width="[\d.]+mm"/,`width="${width}"`).replace(/height="[\d.]+mm"/,`height="${height}"`);url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml;charset=utf-8'}));const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();download(await withDpi(blob,Number($('dpi').value)),'.png');toast('출제용 고화질 PNG를 저장했습니다.')}catch{toast('이미지 저장에 실패했습니다. SVG 저장을 사용하거나 다시 시도하세요.')}finally{if(url)URL.revokeObjectURL(url);btn.disabled=false;btn.textContent='↓ PNG 이미지 저장'}};
$('saveProject').onclick=()=>{download(new Blob([JSON.stringify({format:'blank-map-studio',version:1,state},null,2)],{type:'application/json'}),'.json');toast('다시 편집할 수 있는 작업 파일을 저장했습니다.')};$('loadProject').onclick=()=>$('projectFile').click();
function validState(s){const pair=p=>Array.isArray(p)&&p.length===2&&p.every(n=>Number.isFinite(n)&&Math.abs(n)<=10000),colors=['#d5d5d5','#a9a9a9','#777777','#ffffff','hatch'];return s&&(Object.hasOwn(regions,s.region)||Object.hasOwn(krRegions,s.region))&&(s.atlas===undefined||['world','korea'].includes(s.atlas))&&(s.krLevel===undefined||['kwon','sido','sigungu'].includes(s.krLevel))&&(s.mmW===undefined||s.mmW>=30&&s.mmW<=300)&&(s.mmH===undefined||s.mmH>=30&&s.mmH<=300)&&(s.ratio===undefined||s.ratio>0&&s.ratio<12)&&['clean','exam','contrast'].includes(s.mapStyle)&&['abc','korean','jamo','number','none'].includes(s.symbols)&&colors.includes(s.fill)&&['dashed','solid','none'].includes(s.boundary)&&['kopub','sans','serif'].includes(s.font)&&s.fontSize>=12&&s.fontSize<=80&&(s.autoAssist===undefined||['smart','arrow','ellipse','both','none'].includes(s.autoAssist))&&(s.projection===undefined||Object.hasOwn(projections,s.projection))&&(s.borderWidth===undefined||s.borderWidth>=.4&&s.borderWidth<=3.5)&&(s.coastWidth===undefined||s.coastWidth>=.4&&s.coastWidth<=4)&&(s.seaGray===undefined||s.seaGray>=0&&s.seaGray<=30)&&(s.labelHalo===undefined||typeof s.labelHalo==='boolean')&&(s.autoOrder===undefined||typeof s.autoOrder==='boolean')&&(s.equatorLine===undefined||typeof s.equatorLine==='boolean')&&s.lineWidth>=.4&&s.lineWidth<=2.5&&['equator','grid','frame'].every(k=>typeof s[k]==='boolean')&&s.view&&s.view.k>=.5&&s.view.k<=15&&[s.view.x,s.view.y].every(Number.isFinite)&&Array.isArray(s.countries)&&s.countries.length<=250&&new Set(s.countries.map(c=>c.id)).size===s.countries.length&&s.countries.every(c=>features.some(f=>f.id===c.id)&&pair(c.pos)&&typeof c.text==='string'&&c.text.length<=30&&colors.includes(c.fill)&&(c.size===undefined||Number.isFinite(c.size)&&c.size>=12&&c.size<=80)&&(c.assist===undefined||['inherit','arrow','ellipse','both','none'].includes(c.assist)))&&Array.isArray(s.annotations)&&s.annotations.length<=500&&s.annotations.every(a=>typeof a.id==='string'&&!a.id.startsWith('country:')&&['label','point','line','ellipse'].includes(a.type)&&pair(a.a)&&(a.size===undefined||Number.isFinite(a.size)&&a.size>=12&&a.size<=80)&&(a.halo===undefined||['inherit','on','off'].includes(a.halo))&&(a.dir===undefined||Object.hasOwn(pointDirs,a.dir))&&(a.kind===undefined||a.kind==='sea')&&(['label','point'].includes(a.type)?typeof a.text==='string'&&a.text.length<=30:pair(a.b)&&typeof a.dash==='boolean'))}
$('projectFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();const d=JSON.parse(await file.text());if(d.format!=='blank-map-studio'||d.version!==1||!validState(d.state))throw Error();checkpoint();restore(JSON.stringify(d.state));toast('저장한 작업을 불러왔습니다.')}catch{toast('올바른 백지도 스튜디오 작업 파일을 선택하세요.')}finally{e.target.value=''}};
function setMapSize(mw,mh){state.mmW=Math.max(30,Math.min(300,Math.round(mw)));state.mmH=Math.max(30,Math.min(300,Math.round(mh)));setup();render();syncControls()}
for(const g of document.querySelectorAll('.grip')){g.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();checkpoint();layoutPaper();resizing={axis:g.dataset.grip,x:e.clientX,y:e.clientY,mmW:state.mmW,mmH:state.mmH,scale:paperScale};try{g.setPointerCapture(e.pointerId)}catch{}});g.addEventListener('pointermove',e=>{if(!resizing)return;const s=resizing.scale||1;setMapSize(resizing.axis.includes('w')?resizing.mmW+(e.clientX-resizing.x)/s:state.mmW,resizing.axis.includes('h')?resizing.mmH+(e.clientY-resizing.y)/s:state.mmH)});const stop=e=>{if(!resizing)return;const changed=resizing.mmW!==state.mmW||resizing.mmH!==state.mmH;resizing=null;try{g.releasePointerCapture(e.pointerId)}catch{}if(!changed){history.pop();updateUndo();syncControls();return}state.view={k:1,x:0,y:0};setup();autoArrange();render();renderCountries();syncControls();toast(`지도 크기 ${state.mmW} × ${state.mmH} mm`)};g.addEventListener('pointerup',stop);g.addEventListener('pointercancel',stop)}
window.addEventListener('resize',()=>{if(!resizing)layoutPaper()});
for(const d of document.querySelectorAll('.panel'))d.addEventListener('toggle',()=>{if(!resizing)layoutPaper()});

function addSea(name,pos){const id='annotation-'+Date.now()+'-'+(++uid);let pt=screen(pos);if(!pt||!Number.isFinite(pt[0])||pt[0]<40||pt[0]>W-40||pt[1]<26||pt[1]>H-26)pt=[W/2,H/2];state.annotations.push({id,type:'label',kind:'sea',a:geo(pt)||pos,text:name});return id}
function seaSpot(s){const left=state.equator?Math.max(46,96*autoFontSize()/44):42;let best=null;for(const c of [s.p,...(s.alt?[s.alt]:[])]){const pt=screen(c);if(!pt||!Number.isFinite(pt[0])||!Number.isFinite(pt[1]))continue;const score=Math.min(pt[0]-left,W-46-pt[0],pt[1]-30,H-30-pt[1]);if(!best||score>best.score)best={p:c,pt,score}}return best&&best.score>0?best:null}
function crowded(pt){const gap=state.fontSize*1.6;return [...state.countries.map(c=>screen(c.pos)),...state.annotations.map(a=>screen(a.a))].some(q=>q&&Number.isFinite(q[0])&&Math.hypot(q[0]-pt[0],q[1]-pt[1])<gap)}
$('seaName').onchange=e=>{const hit=seaNames.find(s=>s.t===e.target.value);e.target.value='';if(!hit)return;checkpoint();active=addSea(hit.t,(seaSpot(hit)||{}).p||hit.p);render();toast(`'${hit.t}' 을(를) 넣었습니다. 드래그로 위치를 옮기세요.`)};
$('seaAll').onclick=()=>{const vis=[];for(const s of seaNames){if(!s.major||state.annotations.some(a=>a.text===s.t))continue;const spot=seaSpot(s);if(spot&&!crowded(spot.pt))vis.push({s,spot})}if(!vis.length){toast('넣을 대양 이름이 없습니다. 목록에서 개별로 골라 보세요.');return}checkpoint();for(const v of vis)addSea(v.s.t,v.spot.p);active=null;render();toast(`대양 이름 ${vis.length}개를 넣었습니다.`)};
$('sizePreset').onchange=e=>{const v=e.target.value;if(!v)return;const [w,h]=v.split(',').map(Number);checkpoint();state.mmW=w;state.mmH=h;state.view={k:1,x:0,y:0};setup();autoArrange();syncControls();render();renderCountries();e.target.value='';toast(`지도 크기를 ${w} × ${h} mm 로 바꿨습니다.`)};
$('autoArrange').onclick=()=>{checkpoint();autoArrange();render();toast('선택한 국가의 기호와 안내선을 자동 배치했습니다.')};
$('fontSizeNumber').onchange=()=>{const v=Number($('fontSizeNumber').value);if(!Number.isFinite(v)||v<12||v>80){$('fontSizeNumber').value=state.fontSize;return}state.autoFont=false;$('fontSize').value=v;$('fontSize').dispatchEvent(new Event('change'))};
$('itemSize').onchange=()=>{const a=getActive(),v=Number($('itemSize').value);if(!a)return;if(!Number.isFinite(v)||v<12||v>80){$('itemSize').value=itemSize(a);return}checkpoint();a.size=v;render()};
$('resetItemSize').onclick=()=>{const a=getActive();if(a){checkpoint();delete a.size;render()}};
$('itemDir').onchange=()=>{const a=getActive();if(a){checkpoint();a.dir=$('itemDir').value;render()}};
$('itemHalo').onchange=()=>{const a=getActive();if(a){checkpoint();a.halo=$('itemHalo').value;render()}};
$('itemAssist').onchange=()=>{const a=getActive();if(a&&active?.startsWith('country:')){checkpoint();a.assist=$('itemAssist').value;autoPlaceCountry(a);render()}};
// 이용자 수 카운터.
// VISIT_API 가 비어 있으면 이 기기의 이용 횟수를 세며 외부 요청을 보내지 않습니다.
// 사이트 전체 누적 이용자를 세려면 카운터 API 주소를 여기에 적으세요.
const VISIT_API='';
(function countVisit(){const box=$('visitBox'),out=$('visitCount');if(!out)return;const lab=box&&box.querySelector('.visits-label');const show=(n,note,word)=>{out.textContent=Number(n).toLocaleString('ko-KR');if(box)box.title=note;if(lab&&word)lab.textContent=word};const local=()=>{try{const key='blank-map-studio:visits',n=(Number(localStorage.getItem(key))||0)+1;localStorage.setItem(key,n);show(n,`이 기기에서 ${n}번째 이용`,'이용')}catch{out.textContent='–';if(box)box.title='이용 횟수를 저장할 수 없는 환경입니다.'}};if(!VISIT_API){local();return}fetch(VISIT_API).then(r=>r.ok?r.json():Promise.reject()).then(d=>{const n=d?.count??d?.value??d?.data?.up_count;if(Number.isFinite(Number(n)))show(n,'지금까지 사이트를 이용한 횟수','이용자');else local()}).catch(local)})();
async function loadMapData(){if(window.__BLANK_MAP_DATA)return window.__BLANK_MAP_DATA;const get=async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw Error(`data/${name}.json ${r.status}`);return r.json()};const [countries,land,borders]=await Promise.all([get('countries'),get('land'),get('borders')]);return{countries,land,borders}}
async function init(){let data;try{data=await loadMapData()}catch(err){console.error('지도 자료를 읽지 못했습니다.',err);$('loading').textContent='지도 자료(data/mapdata.js)를 찾지 못했습니다. dist 폴더가 통째로 있는지 확인한 뒤 새로고침하세요.';toast('지도 자료를 불러오지 못했습니다.');return}try{world={features:data.countries.features,land:data.land,borders:data.borders};applyAtlas();ready=true;fillRegionOptions();example(true);updateUndo();$('loading').remove()}catch(err){ready=false;console.error('지도를 그리지 못했습니다.',err);$('loading').textContent='지도를 그리는 중 문제가 생겼습니다. 새로고침해 다시 시도하세요.';toast('지도를 그리지 못했습니다.')}}init();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_blank_map',description:'현재 백지도의 지역과 선택 국가·기호를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){if(!ready)throw Error('지도를 불러오는 중입니다.');return{region:state.region,countries:state.countries.map(c=>({code:c.id,symbol:c.text})),annotations:state.annotations.length}}});register({name:'configure_blank_map',description:'지역과 국가 목록을 설정해 출제용 지도를 편집합니다. 지정한 국가 목록이 현재 목록을 대체하며 되돌릴 수 있습니다.',inputSchema:{type:'object',properties:{region:{type:'string',enum:Object.keys(regions)},countries:{type:'array',items:{type:'string'},maxItems:250},symbols:{type:'string',enum:['abc','korean','jamo','number','none']}},required:['region','countries','symbols'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!ready)throw Error('지도를 불러오는 중입니다.');if(!input||!Object.hasOwn(regions,input.region)||!Array.isArray(input.countries)||input.countries.length>250||!input.countries.every(id=>features.some(f=>f.id===id))||!['abc','korean','jamo','number','none'].includes(input.symbols))throw Error('지역·국가 코드·기호 형식이 올바르지 않습니다.');checkpoint();state.region=input.region;state.symbols=input.symbols;state.countries=[...new Set(input.countries)].map((id,i)=>{const f=features.find(f=>f.id===id);return{id,text:symbol(i),fill:state.fill,pos:[f.properties.LABEL_X,f.properties.LABEL_Y]}});state.view={k:1,x:0,y:0};active=null;setup();syncControls();autoArrange();renderCountries();render();return{region:state.region,selected:state.countries.length}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
